import json, urllib.request, urllib.error, sys
URL="http://127.0.0.1:8765"
def q(files):
    req = urllib.request.Request(URL + "/ignored", data=json.dumps({"files": files}).encode(), headers={"Content-Type": "application/json"})
    try:
        with urllib.request.urlopen(req, timeout=60) as r: return json.load(r)["ignored"]
    except urllib.error.HTTPError as e:
        return ("ERR", e.code, e.read().decode())
def t(pi, paths, sub=None):
    files = {p: None for p in paths}
    if isinstance(pi, dict):
        files.update(pi)
    else:
        files[".packignore"] = pi
    return q(files)
